    public Object parseTicker(Object ticker, Map<String, Object> market)
    {
        String marketId = this.safeString(ticker, "symbol");
        market = (Map<String, Object>) (this.safeMarket(marketId, market));
        Long timestamp = null;
        String bid = null;
        String ask = null;
        String bidVolume = null;
        String askVolume = null;
        String baseVolume = null;
        String quoteVolume = null;
        String open = null;
        String high = null;
        String low = null;
        String changePcnt = null;
        String changeValue = null;
        String prevClose = null;
        Boolean isSwap = (Boolean) this.safeBool(market, "swap");
        // if swap
        if ((java.util.Objects.equals(isSwap, true)) || (((Map<?, ?>)ticker).containsKey("timestamp")))
        {
            //
            //     {
            //         "symbol": "ETH_USDT",
            //         "lastPrice": 3581.3,
            //         "bid1": 3581.25,
            //         "ask1": 3581.5,
            //         "volume24": 4045530,
            //         "amount24": 141331823.5755,
            //         "holdVol": 5832946,
            //         "lower24Price": 3413.4,
            //         "high24Price": 3588.7,
            //         "riseFallRate": 0.0275,
            //         "riseFallValue": 95.95,
            //         "indexPrice": 3580.7852,
            //         "fairPrice": 3581.08,
            //         "fundingRate": 0.000063,
            //         "maxBidPrice": 3938.85,
            //         "minAskPrice": 3222.7,
            //         "timestamp": 1634162885016
            //     }
            //
            timestamp = this.safeInteger(ticker, "timestamp");
            bid = this.safeString(ticker, "bid1");
            ask = this.safeString(ticker, "ask1");
            baseVolume = this.safeString(ticker, "volume24");
            quoteVolume = this.safeString(ticker, "amount24");
            high = this.safeString(ticker, "high24Price");
            low = this.safeString(ticker, "lower24Price");
            changeValue = this.safeString(ticker, "riseFallValue");
            changePcnt = this.safeString(ticker, "riseFallRate");
            changePcnt = Precise.stringMul(changePcnt, "100");
        } else
        {
            //
            //     {
            //         "symbol": "BTCUSDT",
            //         "priceChange": "184.34",
            //         "priceChangePercent": "0.00400048",
            //         "prevClosePrice": "46079.37",
            //         "lastPrice": "46263.71",
            //         "lastQty": "",
            //         "bidPrice": "46260.38",
            //         "bidQty": "",
            //         "askPrice": "46260.41",
            //         "askQty": "",
            //         "openPrice": "46079.37",
            //         "highPrice": "47550.01",
            //         "lowPrice": "45555.5",
            //         "volume": "1732.461487",
            //         "quoteVolume": null,
            //         "openTime": 1641349500000,
            //         "closeTime": 1641349582808,
            //         "count": null
            //     }
            //
            timestamp = this.safeInteger(ticker, "closeTime");
            bid = this.safeString(ticker, "bidPrice");
            ask = this.safeString(ticker, "askPrice");
            bidVolume = this.safeString(ticker, "bidQty");
            askVolume = this.safeString(ticker, "askQty");
            if (Precise.stringEq(bidVolume, "0"))
            {
                bidVolume = null;
            }
            if (Precise.stringEq(askVolume, "0"))
            {
                askVolume = null;
            }
            baseVolume = this.safeString(ticker, "volume");
            quoteVolume = this.safeString(ticker, "quoteVolume");
            open = this.safeString(ticker, "openPrice");
            high = this.safeString(ticker, "highPrice");
            low = this.safeString(ticker, "lowPrice");
            prevClose = this.safeString(ticker, "prevClosePrice");
            changeValue = this.safeString(ticker, "priceChange");
            changePcnt = this.safeString(ticker, "priceChangePercent");
            changePcnt = Precise.stringMul(changePcnt, "100");
        }
        final Map<String, Object> finalMarket = market;
        final Long finalTimestamp = timestamp;
        final String finalOpen = open;
        final String finalHigh = high;
        final String finalLow = low;
        final String finalBid = bid;
        final String finalBidVolume = bidVolume;
        final String finalAsk = ask;
        final String finalAskVolume = askVolume;
        final String finalPrevClose = prevClose;
        final String finalChangeValue = changeValue;
        final String finalChangePcnt = changePcnt;
        final String finalBaseVolume = baseVolume;
        final String finalQuoteVolume = quoteVolume;
        return this.safeTicker(new HashMap<String, Object>() {{
            put( "symbol", ((Map<String, Object>)finalMarket).get("symbol") );
            put( "timestamp", finalTimestamp );
            put( "datetime", Mexc.this.iso8601(finalTimestamp) );
            put( "open", finalOpen );
            put( "high", finalHigh );
            put( "low", finalLow );
            put( "close", Mexc.this.safeString(ticker, "lastPrice") );
            put( "bid", finalBid );
            put( "bidVolume", finalBidVolume );
            put( "ask", finalAsk );
            put( "askVolume", finalAskVolume );
            put( "vwap", null );
            put( "previousClose", finalPrevClose );
            put( "change", finalChangeValue );
            put( "percentage", finalChangePcnt );
            put( "average", null );
            put( "baseVolume", finalBaseVolume );
            put( "quoteVolume", finalQuoteVolume );
            put( "info", ticker );
        }}, market);
    }
    public Object parseTicker(Object ticker, Object... optionalArgs)
    {
        return this.parseTicker(ticker, Helpers.getArgMap(optionalArgs, 0, null));
    }

